# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


def make(last, first, section, email):
    return Student("1", last, first, section, email)


class ContactTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows(
            [
                make("Thistle", "Bram", "A", "b@x.org"),
                make("Quillon", "Ada", "B", "a@x.org")
            ]
        )
        self.assertEqual(
            rows,
            [
                "Quillon, Ada         B        a@x.org",
                "Thistle, Bram        A        b@x.org"
            ]
        )

    def test_missing_email_names_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows([make("Thistle", "Bram", "A", "")])
        text = str(caught.exception)
        self.assertIn("Thistle, Bram", text)

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            contact_rows([])
